import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext(null);

const STORAGE_KEY = 'luxewood_user';

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  useEffect(() => {
    try {
      if (user) localStorage.setItem(STORAGE_KEY, JSON.stringify(user));
      else localStorage.removeItem(STORAGE_KEY);
    } catch {}
  }, [user]);

  // Симульована реєстрація (без бекенду)
  const register = ({ name, email, password }) => {
    const newUser = {
      id: Date.now(),
      name,
      email,
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}`,
      joinedAt: new Date().toISOString(),
      orders: [],
    };
    setUser(newUser);
    return { success: true };
  };

  // Симульований логін
  const login = ({ email, password }) => {
    if (!email || !password) return { success: false, error: 'Заповніть усі поля' };
    // У реальному проекті тут буде запит до API
    const mockUser = {
      id: 1,
      name: email.split('@')[0],
      email,
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(email)}`,
      joinedAt: new Date().toISOString(),
      orders: [],
    };
    setUser(mockUser);
    return { success: true };
  };

  const logout = () => setUser(null);

  const updateProfile = (data) => {
    setUser(prev => ({ ...prev, ...data }));
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, register, updateProfile, isAuth: !!user }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
}
